  # Heroicons are drawn for a 1.5 stroke at 24 px; at the small sizes used
  # here (11 to 16 px) that line is too faint, so it is drawn at 2.
  def icon(name, label: nil, size: 14)
    attributes = label ? { role: "img", "aria-label": label } : { "aria-hidden": "true" }
    content_tag(:svg, ICONS.fetch(name).html_safe, class: "icon", viewBox: "0 0 24 24", width: size, height: size,
                fill: "none", stroke: "currentColor", "stroke-width": size <= 16 ? 2 : 1.5, "stroke-linecap": "round",
                "stroke-linejoin": "round", **attributes)
  end
end
